#!/bin/zsh
export PATH="/opt/homebrew/bin:/usr/local/bin:/usr/bin:/bin:/usr/sbin:/sbin:$PATH"
BASE="${notes_folder:-$HOME/Library/Mobile Documents/iCloud~md~obsidian/Documents/csaborio}"
QUERY="${1:-}"
[[ "$QUERY" == "(null)" ]] && QUERY=""

PYTHON=""
for candidate in /opt/homebrew/bin/python3 /usr/local/bin/python3 "${commands[python3]}" /usr/bin/python3; do
    [[ -x "$candidate" ]] || continue
    # Avoid invoking Apple's developer-tool stub when no tools are installed.
    if [[ "$candidate" == /usr/bin/python3 ]]; then
        /usr/bin/xcode-select -p >/dev/null 2>&1 || continue
    fi
    if "$candidate" -c 'import sys; sys.exit(sys.version_info < (3, 6))' >/dev/null 2>&1; then
        PYTHON="$candidate"
        break
    fi
done
if [[ -z "$PYTHON" ]]; then
    print -r -- '{"items":[{"title":"Python 3 is required","subtitle":"Install Python 3 using the instructions in this workflow’s About page.","valid":false}]}'
    exit 0
fi

"$PYTHON" - "$BASE" "$QUERY" <<'PY'
import os, sys, json, re, signal

base, query = sys.argv[1], sys.argv[2]
base = os.path.expandvars(os.path.expanduser(base))
def message(title, subtitle):
    return {"title": title, "subtitle": subtitle, "valid": False}

if not os.path.isdir(base):
    print(json.dumps({"items": [message("Notes folder not found", "Check Notes folder in workflow configuration: " + base)]}))
    sys.exit(0)

q = query.lower().strip()
items = []
errors = []
markdown_count = 0

def read_snippet(path, term):
    try:
        text = open(path, "r", encoding="utf-8", errors="ignore").read()
        text = re.sub(r"\s+", " ", text).strip()
        if not term:
            return text[:180]
        i = text.lower().find(term)
        if i == -1:
            return text[:180]
        start = max(0, i - 70)
        end = min(len(text), i + 140)
        return ("…" if start else "") + text[start:end] + ("…" if end < len(text) else "")
    except OSError as exc:
        errors.append(str(exc))
        return ""

# Return filename matches before attempting reads that may wait on iCloud.
class ScanTimeout(Exception):
    pass

def timed_out(signum, frame):
    raise ScanTimeout()

signal.signal(signal.SIGALRM, timed_out)
signal.setitimer(signal.ITIMER_REAL, 5)
try:
    candidates = []
    for root, dirs, files in os.walk(base, onerror=lambda exc: errors.append(str(exc))):
        dirs[:] = [d for d in dirs if not d.startswith(".")]
        for f in files:
            if not f.lower().endswith(".md"):
                continue
            markdown_count += 1
            full_path = os.path.join(root, f)
            rel_path = os.path.relpath(full_path, base)
            candidates.append((f, full_path, rel_path))

    def add_note(f, full_path, subtitle):
        items.append({
            "uid": full_path, "type": "file", "title": f,
            "subtitle": subtitle, "arg": full_path,
            "quicklookurl": full_path,
            "icon": {"type": "fileicon", "path": full_path}
        })

    for f, full_path, rel_path in candidates:
        if not q or q in rel_path.lower():
            add_note(f, full_path, rel_path)
            if len(items) >= 100:
                break

    # Content search is a fallback when there are no filename/path matches.
    if q and not items:
        for f, full_path, rel_path in candidates:
            snippet = read_snippet(full_path, q)
            if q in snippet.lower():
                add_note(f, full_path, snippet)
                if len(items) >= 100:
                    break
except ScanTimeout:
    errors.append("Search timed out. Download the vault in Finder, then retry.")
finally:
    signal.setitimer(signal.ITIMER_REAL, 0)

results = items[:100]
if errors:
    results.append(message("Some notes could not be read", "Check folder access and iCloud downloads. " + errors[0]))
if not results:
    results.append(message("No matching notes" if markdown_count else "No Markdown files found",
                           "Try another search." if markdown_count else "Check the configured folder and download the vault in Finder."))
print(json.dumps({"items": results}))
PY
